import kotlinx.coroutines.*

fun main() = runBlocking {
    val job = launch {
        repeat(5) { i ->
            println("tick $i")
            delay(200)
        }
    }
    delay(500)
    job.cancelAndJoin()
    println("cancelled")
}

import kotlinx.coroutines.*

fun main() = runBlocking {
    val job = launch {
        try {
            delay(1000)
        } finally {
            println("cleanup start")
            delay(10)
            println("cleanup end")
        }
    }
    delay(50)
    job.cancelAndJoin()
    println("done")
}

import kotlinx.coroutines.*

fun main() = runBlocking {
    val parent = launch {
        launch { delay(1000); println("child A") }
        launch { delay(1000); println("child B") }
    }
    delay(100)
    parent.cancel()
    parent.join()
    println("${parent.isCancelled} ${parent.isCompleted}")
}
